describe("extraUnsealPasswords", () => {
  const pwA = "A".repeat(40);
  const pwB = "B".repeat(40);
  const pwC = "C".repeat(40);

  const extraConfig = (
    extraUnsealPasswords: string[],
    overrides: Partial<SessionConfig> = {},
  ): SessionConfig => ({
    name: "h3-extra",
    password: pwA,
    extraUnsealPasswords,
    generateId: () => "fresh",
    ...overrides,
  });
  const sealedWith = (password: string, createdAt = Date.now()) =>
    seal({ id: "ext-1", createdAt, data: { foo: "bar" } }, password, sealDefaults);
  const legacySealedWith = (password: string) =>
    seal({ id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } }, password, {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    });
  const setCookieValue = (res: Response) =>
    decodeURIComponent(
      res.headers
        .getSetCookie()
        .find((c) => c.startsWith("h3-extra="))!
        .match(/h3-extra=([^;]+)/)![1],
    );
  const addRoute = (path: string, config: SessionConfig) => {
    t.app.all(path, async (event) => {
      const session = await useSession(event, config);
      if (event.req.method === "POST") {
        await session.update((await readBody(event)) as any);
      }
      return { id: session.id, data: session.data };
    });
  };

  it("reads a session sealed with an extra password", async () => {
    addRoute("/extra-read", extraConfig([pwB]));
    const res = await t.fetch("/extra-read", {
      headers: { Cookie: `h3-extra=${await sealedWith(pwB)}` },
    });
    expect(await res.json()).toMatchObject({ id: "ext-1", data: { foo: "bar" } });
  });

  it("seals the updated session with the main password only", async () => {
    addRoute("/extra-write", extraConfig([pwB]));
    const res = await t.fetch("/extra-write", {
      method: "POST",
      headers: { Cookie: `h3-extra=${await sealedWith(pwB)}` },
      body: JSON.stringify({ baz: "qux" }),
    });
    expect(await res.json()).toMatchObject({ id: "ext-1", data: { foo: "bar", baz: "qux" } });
    const resealed = setCookieValue(res);
    expect(await unseal(resealed, pwA, sealDefaults)).toMatchObject({ id: "ext-1" });
    await expect(unseal(resealed, pwB, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("tries extra passwords in order and stops at the first that opens the seal", async () => {
    addRoute("/extra-order", extraConfig([pwB, pwC]));
    const res = await t.fetch("/extra-order", {
      headers: { Cookie: `h3-extra=${await sealedWith(pwB)}` },
    });
    expect(await res.json()).toMatchObject({ id: "ext-1", data: { foo: "bar" } });
  });

  it("accepts a password repeated in password and extraUnsealPasswords", async () => {
    addRoute("/extra-repeat", extraConfig([pwA]));
    const res = await t.fetch("/extra-repeat", {
      headers: { Cookie: `h3-extra=${await sealedWith(pwA)}` },
    });
    expect(await res.json()).toMatchObject({ id: "ext-1", data: { foo: "bar" } });
  });

  it("starts a new session when no configured password opens the seal", async () => {
    addRoute("/extra-unknown", extraConfig([pwB]));
    const res = await t.fetch("/extra-unknown", {
      headers: { Cookie: `h3-extra=${await sealedWith(pwC)}` },
    });
    expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
  });

  it("starts a new session for an unknown password without extras", async () => {
    addRoute("/extra-none", extraConfig([]));
    const res = await t.fetch("/extra-none", {
      headers: { Cookie: `h3-extra=${await sealedWith(pwC)}` },
    });
    expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
  });

  it("starts a new session for an expired seal opened with an extra password", async () => {
    addRoute("/extra-expired", extraConfig([pwB], { maxAge: 60 }));
    const res = await t.fetch("/extra-expired", {
      headers: { Cookie: `h3-extra=${await sealedWith(pwB, Date.now() - 120_000)}` },
    });
    expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
  });

  for (const bad of ["", "x".repeat(31)]) {
    it(`rejects an invalid extra password (length ${bad.length}) on read`, async () => {
      addRoute("/extra-invalid-read", extraConfig([bad]));
      const res = await t.fetch("/extra-invalid-read", {
        headers: { Cookie: `h3-extra=${await sealedWith(pwA)}` },
      });
      expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
    });

    it(`rejects an invalid extra password (length ${bad.length}) on write`, async () => {
      t.app.post("/extra-invalid-write", async (event) => {
        try {
          await updateSession(event, extraConfig([bad]), { foo: "bar" });
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      const res = await t.fetch("/extra-invalid-write", { method: "POST" });
      expect(await res.json()).toEqual({
        error: "Password string too short (min 32 characters required)",
      });
    });
  }

  it("reseals a legacy seal opened with an extra password using the main password", async () => {
    addRoute("/extra-legacy", extraConfig([pwB]));
    const res = await t.fetch("/extra-legacy", {
      headers: { Cookie: `h3-extra=${await legacySealedWith(pwB)}` },
    });
    expect(await res.json()).toMatchObject({ id: "legacy", data: { foo: "legacy" } });
    const setCookies = res.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    const resealed = setCookieValue(res);
    expect(await unseal(resealed, pwA, sealDefaults)).toMatchObject({ id: "legacy" });
  });

  it("does not open a legacy seal with an extra password when legacySealFallback is false", async () => {
    addRoute("/extra-legacy-strict", extraConfig([pwB], { legacySealFallback: false }));
    const res = await t.fetch("/extra-legacy-strict", {
      headers: { Cookie: `h3-extra=${await legacySealedWith(pwB)}` },
    });
    expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
  });
});

